// Explicit public snapshots only. Ordinary coastal reads never call this saver.
export const COASTAL_PREFIX='sc-coastal-snapshot-';
export const COASTAL_INDEX='sc-coastal-index';
export const COASTAL_META='/__skippercast-coastal.json';
export const COASTAL_PRODUCTS=Object.freeze([{path:'/api/coast/report',limit:8*1024*1024},{path:'/api/coast/ocean',limit:8*1024*1024},{path:'/api/coast/history',limit:16*1024*1024}].map(Object.freeze));
export const COASTAL_REQUEST_TIMEOUT=20000;
export const COASTAL_TOTAL_LIMIT=32*1024*1024;
const locks=new WeakMap();let sequence=0;
function settings(options){const origin=new URL(options.origin).origin;if(new URL(options.origin).href!==origin+'/'&&options.origin!==origin)throw Error('Expected a same-origin base');return {...options,origin,caches:options.caches??globalThis.caches,fetcher:options.fetcher??globalThis.fetch,locks:options.locks??globalThis.navigator?.locks,now:options.now??(()=>new Date())};}
export function canMutateCoastalSnapshot(options={}){return !!(options.caches??globalThis.caches)&&(typeof window==='undefined'||!!(options.locks??globalThis.navigator?.locks)?.request);}
function mutationSupported(options){if(!canMutateCoastalSnapshot(options))throw Error('Safe offline snapshot changes require browser Web Locks');}
function check(signal){if(signal?.aborted)throw signal.reason??new DOMException('Cancelled','AbortError');}
async function locked(storage,work,manager,origin){if(!storage)throw Error('Offline storage unavailable');const previous=locks.get(storage)??Promise.resolve();const task=previous.catch(()=>{}).then(()=>manager?.request?manager.request('skippercast-coastal-snapshot:'+origin,work):work());locks.set(storage,task);try{return await task;}finally{if(locks.get(storage)===task)locks.delete(storage);}}
const key=(origin,path)=>new URL(path,origin).href;
function validDescriptor(value,now){return value?.schema_version===1&&typeof value.cache==='string'&&/^sc-coastal-snapshot-[a-z0-9-]+$/.test(value.cache)&&value.cache.length<=160&&typeof value.saved_at==='string'&&Number.isFinite(Date.parse(value.saved_at))&&Date.parse(value.saved_at)<=now&&Number.isSafeInteger(value.bytes)&&value.bytes>0&&value.bytes<=COASTAL_TOTAL_LIMIT&&Array.isArray(value.products)&&value.products.length===3&&COASTAL_PRODUCTS.every(({path,limit})=>value.products.filter(p=>p&&typeof p==='object'&&p.path===path&&Number.isSafeInteger(p.bytes)&&p.bytes>0&&p.bytes<=limit&&typeof p.generated_at==='string'&&Number.isFinite(Date.parse(p.generated_at))).length===1)&&value.products.reduce((n,p)=>n+p.bytes,0)===value.bytes;}
function validProduct(path,body,now){const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);if(!object(body)||body.schemaVersion!==1||body.countyId!=='slo'||typeof body.generatedAt!=='string'||!Number.isFinite(Date.parse(body.generatedAt))||Date.parse(body.generatedAt)>now)return false;if(path==='/api/coast/report')return ['forecasts','observations','tides','tideEvents','alerts','sources','catches'].every(name=>Array.isArray(body[name]))&&object(body.visibility);if(path==='/api/coast/ocean')return Array.isArray(body.currents)&&Array.isArray(body.sources);if(path==='/api/coast/history')return Array.isArray(body.stations)&&Number.isFinite(body.recentWindowDays)&&body.recentWindowDays>0;return false;}
async function pointer(options){if(!await options.caches.has(COASTAL_INDEX))return null;const index=await options.caches.open(COASTAL_INDEX),response=await index.match(key(options.origin,COASTAL_META));if(!response)return null;let descriptor;try{descriptor=await response.json();}catch{return null;}return validDescriptor(descriptor,options.now().getTime())&&response.status===200&&response.headers.get('X-SC-Saved-At')===descriptor.saved_at?descriptor:null;}
async function removeCache(storage,name){const removed=await storage.delete(name);if(!removed&&await storage.has(name))throw Error('Could not delete coastal cache '+name);return removed;}
// Cache Storage is origin-scoped. Only this exact delimited family is swept.
async function sweep(storage,preserve=null){const names=(await storage.keys()).filter(name=>name.startsWith(COASTAL_PREFIX)&&name!==preserve),errors=[];for(const name of names)try{await removeCache(storage,name);}catch(error){errors.push(error);}if(errors.length)throw new AggregateError(errors,'Coastal snapshot cleanup failed');return names.length;}
/** Read only the currently committed complete snapshot, never scan candidates. */
export async function readCoastalSnapshot(options){const o=settings(options);return locked(o.caches,async()=>{const descriptor=await pointer(o);if(!descriptor||!await o.caches.has(descriptor.cache))return null;const cache=await o.caches.open(descriptor.cache),metadata=await cache.match(key(o.origin,COASTAL_META));if(!metadata||metadata.status!==200||metadata.headers.get('X-SC-Saved-At')!==descriptor.saved_at)return null;let value;try{value=await metadata.json();}catch{return null;}if(JSON.stringify(value)!==JSON.stringify(descriptor))return null;for(const {path,limit} of COASTAL_PRODUCTS){const stored=await cache.match(key(o.origin,path));if(!stored||stored.status!==200||stored.headers.get('X-SC-Saved-At')!==descriptor.saved_at||!/^application\/json(?:\s*;|$)/i.test(stored.headers.get('Content-Type')??''))return null;try{const bytes=await bounded(stored,limit,AbortSignal.timeout(COASTAL_REQUEST_TIMEOUT)),body=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)),product=descriptor.products.find(p=>p.path===path);if(bytes.byteLength!==product.bytes||body.generatedAt!==product.generated_at||!validProduct(path,body,o.now().getTime()))return null;}catch{return null;}}return descriptor;},o.locks,o.origin);}
async function bounded(response,limit,signal){if(!/^application\/json(?:\s*;|$)/i.test(response.headers.get('Content-Type')??'')){void response.body?.cancel().catch(()=>{});throw Error('Snapshot requires original application/json MIME');}if(response.headers.has('X-SC-Offline')){void response.body?.cancel().catch(()=>{});throw Error('Saved offline responses cannot create a fresh snapshot');}if(response.status!==200||!['basic','cors','default'].includes(response.type)||!response.body)throw Error('Complete readable snapshot unavailable');const declared=response.headers.get('Content-Length');if(declared!==null&&(!/^\d+$/.test(declared)||Number(declared)>limit)){void response.body.cancel().catch(()=>{});throw Error('Snapshot exceeds byte budget');}const reader=response.body.getReader(),parts=[];let count=0;const abort=()=>{void reader.cancel(signal.reason).catch(()=>{});};signal?.addEventListener('abort',abort,{once:true});try{while(true){check(signal);const {done,value}=await reader.read();check(signal);if(done)break;count+=value.byteLength;if(count>limit){void reader.cancel().catch(()=>{});throw Error('Snapshot exceeds byte budget');}parts.push(value);}}catch(error){void reader.cancel(error).catch(()=>{});throw error;}finally{signal?.removeEventListener('abort',abort);reader.releaseLock();}const bytes=new Uint8Array(count);let at=0;for(const part of parts){bytes.set(part,at);at+=part.byteLength;}return bytes;}
/** Write a candidate first. One atomic index put commits all three products. */
export async function saveCoastalSnapshot(options){const o=settings(options);mutationSupported(o);return locked(o.caches,async()=>{
 check(o.signal);const at=o.now();if(!(at instanceof Date)||!Number.isFinite(at.getTime()))throw Error('Invalid save clock');const saved_at=at.toISOString(),name=COASTAL_PREFIX+at.getTime()+'-'+(++sequence)+'-'+Math.random().toString(36).slice(2),old=await pointer(o);await sweep(o.caches,old?.cache??null);check(o.signal);let committed=false;
 try{const cache=await o.caches.open(name),products=[];let total=0;
  for(const {path,limit} of COASTAL_PRODUCTS){check(o.signal);const deadline=AbortSignal.timeout(COASTAL_REQUEST_TIMEOUT),signal=o.signal?AbortSignal.any([o.signal,deadline]):deadline;const response=await o.fetcher(key(o.origin,path),{method:'GET',credentials:'omit',redirect:'error',headers:{'X-SC-Offline-Save':'1'},signal});const bytes=await bounded(response,limit,signal),body=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));if(!validProduct(path,body,o.now().getTime()))throw Error('Invalid original snapshot product shape, binding or generated clock');total+=bytes.byteLength;if(total>COASTAL_TOTAL_LIMIT)throw Error('Combined snapshot exceeds byte budget');const headers=new Headers(response.headers);headers.set('X-SC-Saved-At',saved_at);await cache.put(key(o.origin,path),new Response(bytes,{status:200,headers}));products.push({path,bytes:bytes.byteLength,generated_at:body.generatedAt});}
  check(o.signal);const descriptor={schema_version:1,cache:name,saved_at,bytes:total,products},metadata=new Response(JSON.stringify(descriptor),{headers:{'Content-Type':'application/json','X-SC-Saved-At':saved_at}});await cache.put(key(o.origin,COASTAL_META),metadata.clone());check(o.signal);const index=await o.caches.open(COASTAL_INDEX);await index.put(key(o.origin,COASTAL_META),metadata);committed=true;try{await sweep(o.caches,name);}catch(cause){const error=new Error('New coastal snapshot saved, but obsolete cache cleanup failed',{cause});error.committed=true;error.descriptor=descriptor;throw error;}return descriptor;
 }finally{if(!committed)await removeCache(o.caches,name);}
 },o.locks,o.origin);}
/** Remove the index and every cache in this family, including orphaned candidates.
 * Cleanup errors reject; callers must not report successful deletion. */
export async function deleteCoastalSnapshot(options){const o=settings(options);mutationSupported(o);return locked(o.caches,async()=>{const indexRemoved=await removeCache(o.caches,COASTAL_INDEX),removed=await sweep(o.caches);return indexRemoved||removed>0;},o.locks,o.origin);}
